    /// I liked this: a heart in two strokes that meet below.
    case heart = "heart"
    /// I liked this: a heart in two strokes that meet below. (the `active` twin)
    case heartActive = "heart.active"
    /// I liked this: a petroglyph handprint.
    case hand = "hand"
    /// I liked this: a petroglyph handprint. (the `active` twin)
    case handActive = "hand.active"
    /// I liked this: two cords hooked into each other.
    case node = "node"
    /// I liked this: two cords hooked into each other. (the `active` twin)
    case nodeActive = "node.active"
    /// I liked this: a round fruit with a crossed stem.
    case orange = "orange"
    /// I liked this: a round fruit with a crossed stem. (the `active` twin)
    case orangeActive = "orange.active"
    /// I liked this: a heart drawn in one stroke that almost meets.
    case heartHeart = "heart-heart"
    /// I liked this: a heart drawn in one stroke that almost meets. (the `active` twin)
    case heartHeartActive = "heart-heart.active"
    /// I liked this: a spiral inside a stone ring.
    case petroglyph = "petroglyph"
    /// I liked this: a spiral inside a stone ring. (the `active` twin)
    case petroglyphActive = "petroglyph.active"
    /// Ordered steps: a rail with two stone nodes.
    case connection = "connection"
    /// Ordered steps: a tally strap with two notches.
    case timeline = "timeline"
    /// The marks a user scribbles on a stone: a stone ring around a small scribble.
    case pebbleOutlinedGlyph = "pebble-outlined-glyph"
    /// The marks a user scribbles on a stone: a stone ring around a small scribble. (the `lit-1` twin)
    case pebbleOutlinedGlyphLit1 = "pebble-outlined-glyph.lit-1"
    /// The marks a user scribbles on a stone: a stone ring around a small scribble, drawn with an open start.
    case pebbleOutlinedGlyph2 = "pebble-outlined-glyph-2"
    /// The marks a user scribbles on a stone: a stone ring around a small scribble, drawn with an open start. (the
    /// `lit-1` twin)
    case pebbleOutlinedGlyph2Lit1 = "pebble-outlined-glyph-2.lit-1"
    /// Join the community: a speech bubble with its tail at the lower left and a handset inside, the WhatsApp mark in
    /// the set's line.
    case whatsapp = "whatsapp"

    /// The image's name in `Icons.xcassets`: `pbbls-<name>-<variant>`.
    var assetName: String {
        "pbbls-" + rawValue.split(whereSeparator: { $0 == "." || $0 == "-" }).joined(separator: "-")
    }

    /// The manifest row this case belongs to: its own name, or its base's for a twin.
    var base: String {
        String(rawValue.prefix { $0 != "." })
    }

    /// The row's `active` twin (the lit seal), or nil when it has none.
    var activeTwin: PbblsIcon? {
        PbblsIcon(rawValue: "\(base).active")
    }

    /// The row's `lit-n` twin (n stones lit, 1...3), or nil when it has none.
    func lit(_ n: Int) -> PbblsIcon? {
        PbblsIcon(rawValue: "\(base).lit-\(n)")
    }
}

/// A `PbblsIcon` drawn as a template image on a square side that follows
/// Dynamic Type through `@ScaledMetric` (24pt at the default size, relative to
/// `.body` unless told otherwise). It takes the ambient foreground style unless
/// `style` is given, and is hidden from accessibility unless `label` is.
struct PbblsIconImage: View {
    private let icon: PbblsIcon
    private let style: AnyShapeStyle?
    private let label: LocalizedStringResource?
    @ScaledMetric private var side: CGFloat

    init(_ icon: PbblsIcon, size: CGFloat = 24, relativeTo textStyle: Font.TextStyle = .body,
         style: AnyShapeStyle? = nil, label: LocalizedStringResource? = nil) {
        self.icon = icon
        self.style = style
        self.label = label
        _side = ScaledMetric(wrappedValue: size, relativeTo: textStyle)
    }

    var body: some View {
        let image = Image(icon.assetName)
            .renderingMode(.template)
            .resizable()
            .scaledToFit()
            .frame(width: side, height: side)
        labelled(styled(image))
    }

    @ViewBuilder
    private func styled<Content: View>(_ content: Content) -> some View {
        if let style {
            content.foregroundStyle(style)
        } else {
            content
        }
    }

    @ViewBuilder
    private func labelled<Content: View>(_ content: Content) -> some View {
        if let label {
            content.accessibilityLabel(Text(label))
        } else {
            content.accessibilityHidden(true)
        }
    }
}
